1	//! `sqlite3` 句柄 — 对齐 C 端 `struct sqlite3` 的内存布局。
2	//!
3	//! C 端 FFI 消费者通过 `sqlite3*` 拿到不透明指针,函数对它的字段做有
4	//! 限的访问(主要通过 `db->aDb[]` / `db->nDb` / `db->mallocFailed` 等)。
5	//! 真实实现中本结构体将膨胀到 ~600 字段,当前 P0 阶段只放核心字段,
6	//! 后续按 Pager/Schema/Vdbe 等子任务逐字段补齐。
7	
8	use std::sync::atomic::{AtomicBool, AtomicI32, Ordering};
9	use std::sync::Mutex;
10	
11	/// 不透明的 sqlite3 数据库连接句柄。
12	///
13	/// `#[repr(C)]` 是必要的:C 端消费者可能直接 cast 已知偏移,我们要
14	/// 保证 `SqliteDb` 在内存中与 C `struct sqlite3` 的字段顺序/大小一致。
15	/// 当前 P0 阶段为最小布局;随 Pager/Schema 接入会补字段。
16	#[repr(C)]
17	pub struct SqliteDb {
18	    /// 已分配的 schema 数组(后续 P3 阶段补)。当前为 null。
19	    pub a_db: *mut SchemaEntry,
20	    /// schema 数量。
21	    pub n_db: i32,
22	    /// malloc 失败标志(对齐 C 端 `db->mallocFailed`)。
23	    pub malloc_failed: AtomicBool,
24	    /// 活跃语句数(防止在 finalize 中误关)。
25	    pub active_stmt_count: AtomicI32,
26	    /// 内部锁。
27	    pub mutex: Mutex<DbMutexInner>,
28	}
29	
30	/// 内部互斥体持有的内容(P0 阶段为空)。
31	#[derive(Default)]
32	pub struct DbMutexInner {
33	    /// 占位
34	    _placeholder: (),
35	}
36	
37	/// Schema 数组元素 — 占位,P3 阶段会展开。
38	#[repr(C)]
39	pub struct SchemaEntry {
40	    /// 占位
41	    _placeholder: (),
42	}
43	
44	impl SqliteDb {
45	    /// 分配一个全新的、空的 db 句柄。
46	    pub fn new() -> Box<Self> {
47	        Box::new(Self {
48	            a_db: std::ptr::null_mut(),
49	            n_db: 0,
50	            malloc_failed: AtomicBool::new(false),
51	            active_stmt_count: AtomicI32::new(0),
52	            mutex: Mutex::new(DbMutexInner::default()),
53	        })
54	    }
55	
56	    /// 标记 malloc 失败(对齐 C 端 `db->mallocFailed = 1`)。
57	    pub fn set_malloc_failed(&self) {
58	        self.malloc_failed.store(true, Ordering::Release);
59	    }
60	
61	    /// 检查 malloc 失败标志(对齐 `db->mallocFailed != 0`)。
62	    pub fn check_malloc_failed(&self) -> bool {
63	        self.malloc_failed.load(Ordering::Acquire)
64	    }
65	}
66	
67	// SAFETY: SqliteDb 内部同步通过 AtomicBool/Mutex;指针字段在
68	// 当前阶段不跨线程共享(P0)。
69	unsafe impl Send for SqliteDb {}
70	unsafe impl Sync for SqliteDb {}
71	
72	#[cfg(test)]
73	mod tests {
74	    use super::*;
75	
76	    #[test]
77	    fn new_db_starts_clean() {
78	        let db = SqliteDb::new();
79	        assert!(!db.check_malloc_failed());
80	        assert_eq!(db.active_stmt_count.load(Ordering::Acquire), 0);
81	    }
82	
83	    #[test]
84	    fn malloc_failed_round_trip() {
85	        let db = SqliteDb::new();
86	        db.set_malloc_failed();
87	        assert!(db.check_malloc_failed());
88	    }
89	}
90

