8	**    May you find forgiveness for yourself and forgive others.
9	**    May you share freely, never taking more than you give.
10	**
11	*************************************************************************
12	** Utility functions used throughout sqlite.
13	**
14	** This file contains functions for allocating memory, comparing
15	** strings, and stuff like that.
16	**
17	*/
18	#include "sqliteInt.h"
19	#include <stdarg.h>
20	#ifndef SQLITE_OMIT_FLOATING_POINT
21	#include <math.h>
22	
23	/* Work around a bug in older Microsoft compilers
24	** Forum post 2026-04-10T06:33:11z */
25	#if !defined(INFINITY) && defined(_MSC_VER)
26	# define INFINITY HUGE_VAL
27	#endif
28	
29	#endif /* SQLITE_OMIT_FLOATING_POINT */
30	
31	/*
32	** Calls to sqlite3FaultSim() are used to simulate a failure during testing,
33	** or to bypass normal error detection during testing in order to let
34	** execute proceed further downstream.
35	**
36	** In deployment, sqlite3FaultSim() *always* return SQLITE_OK (0).  The
37	** sqlite3FaultSim() function only returns non-zero during testing.
38	**
39	** During testing, if the test harness has set a fault-sim callback using
40	** a call to sqlite3_test_control(SQLITE_TESTCTRL_FAULT_INSTALL), then
41	** each call to sqlite3FaultSim() is relayed to that application-supplied
42	** callback and the integer return value form the application-supplied
43	** callback is returned by sqlite3FaultSim().
44	**
45	** The integer argument to sqlite3FaultSim() is a code to identify which
46	** sqlite3FaultSim() instance is being invoked. Each call to sqlite3FaultSim()
47	** should have a unique code.  To prevent legacy testing applications from
48	** breaking, the codes should not be changed or reused.
49	*/
50	#ifndef SQLITE_UNTESTABLE
51	int sqlite3FaultSim(int iTest){
52	  int (*xCallback)(int) = sqlite3GlobalConfig.xTestCallback;
53	  return xCallback ? xCallback(iTest) : SQLITE_OK;
54	}
55	#endif
56	
57	#ifndef SQLITE_OMIT_FLOATING_POINT
58	/*
59	** Return true if the floating point value is Not a Number (NaN).
60	**
61	** Use the math library isnan() function if compiled with SQLITE_HAVE_ISNAN.
62	** Otherwise, we have our own implementation that works on most systems.
63	*/
64	int sqlite3IsNaN(double x){
65	  int rc;   /* The value return */
66	#if !SQLITE_HAVE_ISNAN && !HAVE_ISNAN
67	  u64 y;
68	  memcpy(&y,&x,sizeof(y));
69	  rc = IsNaN(y);
70	#else
71	  rc = isnan(x);
72	#endif /* HAVE_ISNAN */
73	  testcase( rc );
74	  return rc;
75	}
76	#endif /* SQLITE_OMIT_FLOATING_POINT */
77	
78	#ifndef SQLITE_OMIT_FLOATING_POINT
79	/*
80	** Return true if the floating point value is NaN or +Inf or -Inf.
81	*/
82	int sqlite3IsOverflow(double x){
83	  int rc;   /* The value return */
84	  u64 y;
85	  memcpy(&y,&x,sizeof(y));
86	  rc = IsOvfl(y);
87	  return rc;
88	}
89	#endif /* SQLITE_OMIT_FLOATING_POINT */
90	
91	/*
92	** Compute a string length that is limited to what can be stored in
93	** lower 30 bits of a 32-bit signed integer.
94	**
95	** The value returned will never be negative.  Nor will it ever be greater
96	** than the actual length of the string.  For very long strings (greater
97	** than 1GiB) the value returned might be less than the true string length.
98	*/
99	int sqlite3Strlen30(const char *z){
100	  if( z==0 ) return 0;
101	  return 0x3fffffff & (int)strlen(z);
102	}
103	
104	/*
105	** Return the declared type of a column.  Or return zDflt if the column
106	** has no declared type.
107	**
108	** The column type is an extra string stored after the zero-terminator on
109	** the column name if and only if the COLFLAG_HASTYPE flag is set.
110	*/
111	char *sqlite3ColumnType(Column *pCol, char *zDflt){
112	  if( pCol->colFlags & COLFLAG_HASTYPE ){
113	    return pCol->zCnName + strlen(pCol->zCnName) + 1;
114	  }else if( pCol->eCType ){
115	    assert( pCol->eCType<=SQLITE_N_STDTYPE );
116	    return (char*)sqlite3StdType[pCol->eCType-1];
117	  }else{
118	    return zDflt;
119	  }
120	}
121	
122	/*
123	** Helper function for sqlite3Error() - called rarely.  Broken out into
124	** a separate routine to avoid unnecessary register saves on entry to
125	** sqlite3Error().
126	*/
127	static SQLITE_NOINLINE void  sqlite3ErrorFinish(sqlite3 *db, int err_code){
128	  if( db->pErr ) sqlite3ValueSetNull(db->pErr);
129	  sqlite3SystemError(db, err_code);
130	}
131	
132	/*
133	** Set the current error code to err_code and clear any prior error message.
134	** Also set iSysErrno (by calling sqlite3System) if the err_code indicates
135	** that would be appropriate.
136	*/
137	void sqlite3Error(sqlite3 *db, int err_code){
138	  assert( db!=0 );
139	  db->errCode = err_code;
140	  if( err_code || db->pErr ){
141	    sqlite3ErrorFinish(db, err_code);
142	  }else{
143	    db->errByteOffset = -1;
144	  }
145	}
146	
147	/*
148	** The equivalent of sqlite3Error(db, SQLITE_OK).  Clear the error state
149	** and error message.
150	*/
151	void sqlite3ErrorClear(sqlite3 *db){
152	  assert( db!=0 );
153	  db->errCode = SQLITE_OK;
154	  db->errByteOffset = -1;
155	  if( db->pErr ) sqlite3ValueSetNull(db->pErr);
156	}
157	
158	/*
159	** Load the sqlite3.iSysErrno field if that is an appropriate thing
160	** to do based on the SQLite error code in rc.
161	*/
162	void sqlite3SystemError(sqlite3 *db, int rc){
163	  if( rc==SQLITE_IOERR_NOMEM ) return;
164	#if defined(SQLITE_USE_SEH) && !defined(SQLITE_OMIT_WAL)
165	  if( rc==SQLITE_IOERR_IN_PAGE ){
166	    int ii;
167	    int iErr;
168	    sqlite3BtreeEnterAll(db);
169	    for(ii=0; ii<db->nDb; ii++){
170	      if( db->aDb[ii].pBt ){
171	        iErr = sqlite3PagerWalSystemErrno(sqlite3BtreePager(db->aDb[ii].pBt));
172	        if( iErr ){
173	          db->iSysErrno = iErr;
174	        }
175	      }
176	    }
177	    sqlite3BtreeLeaveAll(db);
178	    return;
179	  }
180	#endif
181	  rc &= 0xff;
182	  if( rc==SQLITE_CANTOPEN || rc==SQLITE_IOERR ){
183	    db->iSysErrno = sqlite3OsGetLastError(db->pVfs);
184	  }
185	}
186	
187	/*
188	** Set the most recent error code and error string for the sqlite
189	** handle "db". The error code is set to "err_code".
190	**
191	** If it is not NULL, string zFormat specifies the format of the
192	** error string.  zFormat and any string tokens that follow it are
193	** assumed to be encoded in UTF-8.
194	**
195	** To clear the most recent error for sqlite handle "db", sqlite3Error
196	** should be called with err_code set to SQLITE_OK and zFormat set
197	** to NULL.
198	*/
199	void sqlite3ErrorWithMsg(sqlite3 *db, int err_code, const char *zFormat, ...){
