239	/*
240	** Add an error message to pParse->zErrMsg and increment pParse->nErr.
241	**
242	** This function should be used to report any error that occurs while
243	** compiling an SQL statement (i.e. within sqlite3_prepare()). The
244	** last thing the sqlite3_prepare() function does is copy the error
245	** stored by this function into the database handle using sqlite3Error().
246	** Functions sqlite3Error() or sqlite3ErrorWithMsg() should be used
247	** during statement execution (sqlite3_step() etc.).
248	*/
249	void sqlite3ErrorMsg(Parse *pParse, const char *zFormat, ...){
250	  char *zMsg;
251	  va_list ap;
252	  sqlite3 *db = pParse->db;
253	  assert( db!=0 );
254	  assert( db->pParse==pParse || db->pParse->pToplevel==pParse );
255	  db->errByteOffset = -2;
256	  va_start(ap, zFormat);
257	  zMsg = sqlite3VMPrintf(db, zFormat, ap);
258	  va_end(ap);
259	  if( db->errByteOffset<-1 ) db->errByteOffset = -1;
260	  if( db->suppressErr ){
261	    sqlite3DbFree(db, zMsg);
262	    if( db->mallocFailed ){
263	      pParse->nErr++;
264	      pParse->rc = SQLITE_NOMEM;
265	    }
266	  }else{
267	    pParse->nErr++;
268	    sqlite3DbFree(db, pParse->zErrMsg);
269	    pParse->zErrMsg = zMsg;
270	    pParse->rc = SQLITE_ERROR;
271	    pParse->pWith = 0;
272	  }
273	}
