288	/*
289	** Convert an SQL-style quoted string into a normal string by removing
290	** the quote characters.  The conversion is done in-place.  If the
291	** input does not begin with a quote character, then this routine
292	** is a no-op.
293	**
294	** The input string must be zero-terminated.  A new zero-terminator
295	** is added to the dequoted string.
296	**
297	** The return value is -1 if no dequoting occurs or the length of the
298	** dequoted string, exclusive of the zero terminator, if dequoting does
299	** occur.
300	**
301	** 2002-02-14: This routine is extended to remove MS-Access style
302	** brackets from around identifiers.  For example:  "[a-b-c]" becomes
303	** "a-b-c".
304	*/
305	void sqlite3Dequote(char *z){
306	  char quote;
307	  int i, j;
308	  if( z==0 ) return;
309	  quote = z[0];
310	  if( !sqlite3Isquote(quote) ) return;
311	  if( quote=='[' ) quote = ']';
312	  for(i=1, j=0;; i++){
313	    assert( z[i] );
314	    if( z[i]==quote ){
315	      if( z[i+1]==quote ){
316	        z[j++] = quote;
317	        i++;
318	      }else{
319	        break;
320	      }
321	    }else{
322	      z[j++] = z[i];
323	    }
324	  }
325	  z[j] = 0;
326	}
327	void sqlite3DequoteExpr(Expr *p){
328	  assert( !ExprHasProperty(p, EP_IntValue) );
329	  assert( sqlite3Isquote(p->u.zToken[0]) );
330	  p->flags |= p->u.zToken[0]=='"' ? EP_Quoted|EP_DblQuoted : EP_Quoted;
331	  sqlite3Dequote(p->u.zToken);
332	}
