334	/*
335	** Expression p is a QNUMBER (quoted number). Dequote the value in p->u.zToken
336	** and set the type to INTEGER or FLOAT. "Quoted" integers or floats are those
337	** that contain '_' characters that must be removed before further processing.
338	*/
339	void sqlite3DequoteNumber(Parse *pParse, Expr *p){
340	  assert( p!=0 || pParse->db->mallocFailed );
341	  if( p ){
342	    const char *pIn = p->u.zToken;
343	    char *pOut = p->u.zToken;
344	    int bHex = (pIn[0]=='0' && (pIn[1]=='x' || pIn[1]=='X'));
345	    int iValue;
346	    assert( p->op==TK_QNUMBER );
347	    p->op = TK_INTEGER;
348	    do {
349	      if( *pIn!=SQLITE_DIGIT_SEPARATOR ){
350	        *pOut++ = *pIn;
351	        if( *pIn=='e' || *pIn=='E' || *pIn=='.' ) p->op = TK_FLOAT;
352	      }else{
353	        if( (bHex==0 && (!sqlite3Isdigit(pIn[-1]) || !sqlite3Isdigit(pIn[1])))
354	         || (bHex==1 && (!sqlite3Isxdigit(pIn[-1]) || !sqlite3Isxdigit(pIn[1])))
355	        ){
356	          sqlite3ErrorMsg(pParse, "unrecognized token: \"%s\"", p->u.zToken);
357	        }
358	      }
359	    }while( *pIn++ );
360	    if( bHex ) p->op = TK_INTEGER;
361	
362	    /* tag-20240227-a: If after dequoting, the number is an integer that
363	    ** fits in 32 bits, then it must be converted into EP_IntValue.  Other
364	    ** parts of the code expect this.  See also tag-20240227-b. */
365	    if( p->op==TK_INTEGER && sqlite3GetInt32(p->u.zToken, &iValue) ){
366	      p->u.iValue = iValue;
367	      p->flags |= EP_IntValue;
368	    }
369	  }
370	}
