372	/*
373	** If the input token p is quoted, try to adjust the token to remove
374	** the quotes.  This is not always possible:
375	**
376	**     "abc"     ->   abc
377	**     "ab""cd"  ->   (not possible because of the interior "")
378	**
379	** Remove the quotes if possible.  This is a optimization.  The overall
380	** system should still return the correct answer even if this routine
381	** is always a no-op.
382	*/
383	void sqlite3DequoteToken(Token *p){
384	  unsigned int i;
385	  if( p->n<2 ) return;
386	  if( !sqlite3Isquote(p->z[0]) ) return;
387	  for(i=1; i<p->n-1; i++){
388	    if( sqlite3Isquote(p->z[i]) ) return;
389	  }
390	  p->n -= 2;
391	  p->z++;
392	}
