402	/* Convenient short-hand */
403	#define UpperToLower sqlite3UpperToLower
404	
405	/*
406	** Some systems have stricmp().  Others have strcasecmp().  Because
407	** there is no consistency, we will define our own.
408	**
409	** IMPLEMENTATION-OF: R-30243-02494 The sqlite3_stricmp() and
410	** sqlite3_strnicmp() APIs allow applications and extensions to compare
411	** the contents of two buffers containing UTF-8 strings in a
412	** case-independent fashion, using the same definition of "case
413	** independence" that SQLite uses internally when comparing identifiers.
414	*/
415	int sqlite3_stricmp(const char *zLeft, const char *zRight){
416	  if( zLeft==0 ){
417	    return zRight ? -1 : 0;
418	  }else if( zRight==0 ){
419	    return 1;
420	  }
421	  return sqlite3StrICmp(zLeft, zRight);
422	}
423	int sqlite3StrICmp(const char *zLeft, const char *zRight){
424	  unsigned char *a, *b;
425	  int c, x;
426	  a = (unsigned char *)zLeft;
427	  b = (unsigned char *)zRight;
428	  for(;;){
429	    c = *a;
430	    x = *b;
431	    if( c==x ){
432	      if( c==0 ) break;
433	    }else{
434	      c = (int)UpperToLower[c] - (int)UpperToLower[x];
435	      if( c ) break;
436	    }
437	    a++;
438	    b++;
439	  }
440	  return c;
441	}
442	int sqlite3_strnicmp(const char *zLeft, const char *zRight, int N){
443	  register unsigned char *a, *b;
444	  if( zLeft==0 ){
445	    return zRight ? -1 : 0;
446	  }else if( zRight==0 ){
447	    return 1;
448	  }
449	  a = (unsigned char *)zLeft;
450	  b = (unsigned char *)zRight;
451	  while( N-- > 0 && *a!=0 && UpperToLower[*a]==UpperToLower[*b]){ a++; b++; }
452	  return N<0 ? 0 : UpperToLower[*a] - UpperToLower[*b];
453	}
