455	/*
456	** Compute an 8-bit hash on a string that is insensitive to case differences
457	*/
458	u8 sqlite3StrIHash(const char *z){
459	  u8 h = 0;
460	  if( z==0 ) return 0;
461	  while( z[0] ){
462	    h += UpperToLower[(unsigned char)z[0]];
463	    z++;
464	  }
465	  return h;
466	}
