475	/*
476	** Two inputs are multiplied to get a 128-bit result.  Write the
477	** lower 64-bits of the result into *pLo, and return the high-order
478	** 64 bits.
479	*/
480	static u64 sqlite3Multiply128(u64 a, u64 b, u64 *pLo){
481	#if defined(SQLITE_USE_UINT128)
482	  __uint128_t r = (__uint128_t)a * b;
483	  *pLo = (u64)r;
484	  return (u64)(r>>64);
485	#elif defined(_WIN64) && !defined(SQLITE_DISABLE_INTRINSIC)
486	  *pLo = a*b;
487	  return __umulh(a, b);
488	#else
489	  u64 a0 = (u32)a;
490	  u64 a1 = a >> 32;
491	  u64 b0 = (u32)b;
492	  u64 b1 = b >> 32;
493	  u64 a0b0 = a0 * b0;
494	  u64 a1b1 = a1 * b1;
495	  u64 a0b1 = a0 * b1;
496	  u64 a1b0 = a1 * b0;
497	  u64 t = (a0b0 >> 32) + (u32)a0b1 + (u32)a1b0;
498	  *pLo = (a0b0 & UINT64_C(0xffffffff)) | (t << 32);
499	  return a1b1 + (a0b1>>32) + (a1b0>>32) + (t>>32);
500	#endif
501	}
