503	/*
504	** A is an unsigned 96-bit integer formed by (a<<32)+aLo.
505	** B is an unsigned 64-bit integer.
506	**
507	** Compute the upper 96 bits of 160-bit result of A*B.
508	**
509	** Write ((A*B)>>64 & 0xffffffff) (the middle 32 bits of A*B)
510	** into *pLo.  Return the upper 64 bits of A*B.
511	**
512	** The lower 64 bits of A*B are discarded.
513	*/
514	static u64 sqlite3Multiply160(u64 a, u32 aLo, u64 b, u32 *pLo){
515	#if defined(SQLITE_USE_UINT128)
516	  __uint128_t r = (__uint128_t)a * b;
517	  r += ((__uint128_t)aLo * b) >> 32;
518	  *pLo = (r>>32)&0xffffffff;
519	  return r>>64;
520	#elif defined(_WIN64) && !defined(SQLITE_DISABLE_INTRINSIC)
521	  u64 r1_hi = __umulh(a,b);
522	  u64 r1_lo = a*b;
523	  u64 r2 = (__umulh((u64)aLo,b)<<32) + ((aLo*b)>>32);
524	  u64 t = r1_lo + r2;
525	  if( t<r1_lo ) r1_hi++;
526	  *pLo = t>>32;
527	  return r1_hi;
528	#else
529	  u64 x2 = a>>32;
530	  u64 x1 = a&0xffffffff;
531	  u64 x0 = aLo;
532	  u64 y1 = b>>32;
533	  u64 y0 = b&0xffffffff;
534	  u64 x2y1 = x2*y1;
535	  u64 r4 = x2y1>>32;
536	  u64 x2y0 = x2*y0;
537	  u64 x1y1 = x1*y1;
538	  u64 r3 = (x2y1 & 0xffffffff) + (x2y0 >>32) + (x1y1 >>32);
539	  u64 x1y0 = x1*y0;
540	  u64 x0y1 = x0*y1;
541	  u64 r2 = (x2y0 & 0xffffffff) + (x1y1 & 0xffffffff) +
542	             (x1y0 >>32) + (x0y1>>32);
543	  u64 x0y0 = x0*y0;
544	  u64 r1 = (x1y0 & 0xffffffff) + (x0y1 & 0xffffffff) +
545	             (x0y0 >>32);
546	  r2 += r1>>32;
547	  r3 += r2>>32;
548	  *pLo = r2&0xffffffff;
549	  return (r4<<32) + r3;
550	#endif
551	}
