690	    if( n ){
691	      g--;
692	      n += 27;
693	    }
694	  }else if( p<27 ){
695	    *pLo = 0;
696	    return aBase[p];
697	  }else{
698	    g = p/27;
699	    n = p%27;
700	  }
701	  s = aScale[g+13];
702	  if( n==0 ){
703	    *pLo = aScaleLo[g+13];
704	    return s;
705	  }
706	  x = sqlite3Multiply160(s,aScaleLo[g+13],aBase[n],&lo);
707	  if( (U64_BIT(63) & x)==0 ){
708	    x  = x<<1 | ((lo>>31)&1);
709	    lo = (lo<<1) | 1;
710	  }
711	  *pLo = lo;
712	  return x;
