715	/*
716	** pow10to2(x) computes floor(log2(pow(10,x))).
717	** pow2to10(y) computes floor(log10(pow(2,y))).
718	**
719	** Conceptually, pow10to2(p) converts a base-10 exponent p into
720	** a corresponding base-2 exponent, and pow2to10(e) converts a base-2
721	** exponent into a base-10 exponent.
722	**
723	** The conversions are based on the observation that:
724	**
725	**     ln(10.0)/ln(2.0) == 108853/32768     (approximately)
726	**     ln(2.0)/ln(10.0) == 78913/262144     (approximately)
727	**
728	** These ratios are approximate, but they are accurate to 5 digits,
729	** which is close enough for the usage here.  Right-shift is used
730	** for division so that rounding of negative numbers happens in the
731	** right direction.
732	*/
733	static int pwr10to2(int p){ return (p*108853) >> 15; }
734	static int pwr2to10(int p){ return (p*78913) >> 18; }
