736	/*
737	** Count leading zeros for a 64-bit unsigned integer.
738	*/
739	static int countLeadingZeros(u64 m){
740	#if (defined(__GNUC__) || defined(__clang__)) \
741	    && !defined(SQLITE_DISABLE_INTRINSIC)
742	  return __builtin_clzll(m);
743	#else
744	  int n = 0;
745	  if( m <= 0x00000000ffffffffULL) { n += 32; m <<= 32; }
746	  if( m <= 0x0000ffffffffffffULL) { n += 16; m <<= 16; }
747	  if( m <= 0x00ffffffffffffffULL) { n += 8;  m <<= 8;  }
748	  if( m <= 0x0fffffffffffffffULL) { n += 4;  m <<= 4;  }
749	  if( m <= 0x3fffffffffffffffULL) { n += 2;  m <<= 2;  }
750	  if( m <= 0x7fffffffffffffffULL) { n += 1;            }
751	  return n;
752	#endif
753	}
