755	/*
756	** Given m and e, which represent a quantity r == m*pow(2,e),
757	** return values *pD and *pP such that r == (*pD)*pow(10,*pP),
758	** approximately.  *pD should contain at least n significant digits.
759	**
760	** The input m is required to have its highest bit set.  In other words,
761	** m should be left-shifted, and e decremented, to maximize the value of m.
762	*/
763	static void sqlite3Fp2Convert10(u64 m, int e, int n, u64 *pD, int *pP){
764	  int p;
765	  u64 h, d1;
766	  u32 d2;
767	  assert( n>=1 && n<=18 );
768	  p = n - 1 - pwr2to10(e+63);
769	  h = sqlite3Multiply128(m, powerOfTen(p,&d2), &d1);
770	  assert( -(e + pwr10to2(p) + 2) >= 0  );
771	  assert( -(e + pwr10to2(p) + 1) <= 63 );
772	  if( n==18 ){
773	    h >>= -(e + pwr10to2(p) + 2);
774	    *pD = (h + ((h<<1)&2))>>1;
775	  }else{
776	    *pD = h >> -(e + pwr10to2(p) + 1);
777	  }
778	  *pP = -p;
779	}
