781	/*
782	** Return an IEEE754 floating point value that approximates d*pow(10,p).
783	**
784	** The (current) algorithm is adapted from the work of Ross Cox at
785	** https://github.com/rsc/fpfmt
786	*/
787	static double sqlite3Fp10Convert2(u64 d, int p){
788	  int b, lp, e, adj, s;
789	  u32 pwr10l, mid1;
790	  u64 pwr10h, x, hi, lo, sticky, u, m;
791	  double r;
792	  if( p<POWERSOF10_FIRST ) return 0.0;
793	  if( p>POWERSOF10_LAST ) return (double)INFINITY;
794	  b = 64 - countLeadingZeros(d);
795	  lp = pwr10to2(p);
796	  e = 53 - b - lp;
797	  if( e > 1074 ){
798	    if( e>=1130 ) return 0.0;
799	    e = 1074;
800	  }
801	  s = -(e-(64-b) + lp + 3);
802	  pwr10h = powerOfTen(p, &pwr10l);
803	  if( pwr10l!=0 ){
804	    pwr10h++;
805	    pwr10l = ~pwr10l;
806	  }
807	  x = d<<(64-b);
808	  hi = sqlite3Multiply128(x,pwr10h,&lo);
809	  mid1 = lo>>32;
810	  sticky = 1;
811	  if( (hi & (U64_BIT(s)-1))==0 ) {
812	    u32 mid2 = sqlite3Multiply128(x,((u64)pwr10l)<<32,&lo)>>32;
813	    sticky = (mid1-mid2 > 1);
814	    hi -= mid1 < mid2;
815	  }
816	  u = (hi>>s) | sticky;
817	  adj = (u >= U64_BIT(55)-2);
818	  if( adj ){
819	    u = (u>>adj) | (u&1);
820	    e -= adj;
821	  }
822	  m = (u + 1 + ((u>>2)&1)) >> 2;
823	  if( e<=(-972) ) return (double)INFINITY;
824	  if((m & U64_BIT(52)) != 0){
825	    m = (m & ~U64_BIT(52)) | ((u64)(1075-e)<<52);
826	  }
827	  memcpy(&r,&m,8);
828	  return r;
829	}
