831	/*
832	** The string z[] is an text representation of a real number.
833	** Convert this string to a double and write it into *pResult.
834	**
835	** z[] must be UTF-8 and zero-terminated.
836	**
837	** Return positive if the result is a valid real number (or integer) and
838	** zero or negative if the string is empty or contains extraneous text.
839	** Lower bits of the return value contain addition information about the
840	** parse:
841	**
842	**   bit 0       =>   Set if any prefix of the input is valid.  Clear if
843	**                    there is no prefix of the input that can be seen as
844	**                    a valid floating point number.
845	**   bit 1       =>   Set if the input contains a decimal point or eNNN
846	**                    clause.  Zero if the input is an integer.
847	**   bit 2       =>   The input is exactly 0.0, not an underflow from
848	**                    some value near zero.
849	**   bit 3       =>   Set if there are more than about 19 significant
850	**                    digits in the input.
851	**
852	** If the input contains a syntax error but begins with text that might
853	** be a valid number of some kind, then the result is negative.  The
854	** result is only zero if no prefix of the input could be interpreted as
855	** a number.
856	**
857	** Leading and trailing whitespace is ignored.  Valid numbers are in
858	** one of the formats below:
859	**
860	**    [+-]digits[E[+-]digits]
861	**    [+-]digits.[digits][E[+-]digits]
862	**    [+-].digits[E[+-]digits]
863	**
864	** Algorithm sketch:  Compute an unsigned 64-bit integer s and a base-10
865	** exponent d such that the value encoding by the input is s*pow(10,d).
866	** Then invoke sqlite3Fp10Convert2() to calculated the closest possible
867	** IEEE754 double.  The sign is added back afterwards, if the input string
868	** starts with a "-".  The use of an unsigned 64-bit s mantissa means that
869	** only about the first 19 significant digits of the input can contribute
870	** to the result.  This can result in suboptimal rounding decisions when
871	** correct rounding requires more than 19 input digits.  For example,
872	** this routine renders "3500000000000000.2500001" as
873	** 3500000000000000.0 instead of 3500000000000000.5 because the decision
874	** to round up instead of using banker's rounding to round down is determined
875	** by the 23rd significant digit, which this routine ignores. It is not
876	** possible to do better without some kind of BigNum.
877	*/
878	int sqlite3AtoF(const char *zIn, double *pResult){
879	#ifndef SQLITE_OMIT_FLOATING_POINT
880	  const unsigned char *z = (const unsigned char*)zIn;
881	  int neg = 0;       /* True for a negative value */
882	  u64 s = 0;         /* mantissa */
883	  int d = 0;         /* Value is s * pow(10,d) */
884	  int mState = 0;    /* 1: digit seen 2: fp 4: hard-zero */
885	  unsigned v;        /* Value of a single digit */
886	
887	  start_of_text:
888	  if( (v = (unsigned)z[0] - '0')<10 ){
889	    parse_integer_part:
890	    mState = 1;
891	    s = v;
892	    z++;
893	    while( (v = (unsigned)z[0] - '0')<10 ){
894	      s = s*10 + v;
895	      z++;
896	      if( s>=(LARGEST_UINT64-9)/10 ){
897	        mState = 9;
898	        while( sqlite3Isdigit(z[0]) ){ z++; d++; }
899	        break;
900	      }
901	    }
902	  }else if( z[0]=='-' ){
903	    neg = 1;
904	    z++;
905	    if( (v = (unsigned)z[0] - '0')<10 ) goto parse_integer_part;
906	  }else if( z[0]=='+' ){
907	    z++;
908	    if( (v = (unsigned)z[0] - '0')<10 ) goto parse_integer_part;
909	  }else if( sqlite3Isspace(z[0]) ){
910	    do{ z++; }while( sqlite3Isspace(z[0]) );
911	    goto start_of_text;
912	  }else{
913	    s = 0;
914	  }
915	
916	  /* if decimal point is present */
917	  if( *z=='.' ){
918	    z++;
919	    if( sqlite3Isdigit(z[0]) ){
920	      mState |= 1;
921	      do{
922	        if( s<(LARGEST_UINT64-9)/10 ){
923	          s = s*10 + z[0] - '0';
924	          d--;
925	        }else{
926	          mState = 11;
927	        }
928	      }while( sqlite3Isdigit(*++z) );
929	    }else if( mState==0 ){
930	      *pResult = 0.0;
931	      return 0;
932	    }
933	    mState |= 2;
934	  }else if( mState==0 ){
935	    *pResult = 0.0;
936	    return 0;
937	  }
938	
939	  /* if exponent is present */
940	  if( *z=='e' || *z=='E' ){
941	    int esign;
942	    z++;
943	 
944	    /* get sign of exponent */
945	    if( *z=='-' ){
946	      esign = -1;
947	      z++;
948	    }else{
949	      esign = +1;
950	      if( *z=='+' ){
951	        z++;
952	      }
953	    }
954	    /* copy digits to exponent */
955	    if( (v = (unsigned)z[0] - '0')<10 ){
956	      int exp = v;
957	      z++;
958	      mState |= 2;
959	      while( (v = (unsigned)z[0] - '0')<10 ){
960	        exp = exp<10000 ? (exp*10 + v) : 10000;
961	        z++;
962	      }
963	      d += esign*exp;
964	    }else{
965	      z--;  /* Leave z[0] at 'e' or '+' or '-',
966	            ** so that the return is 0 or -1 */
967	    }
968	  }
969	
970	  /* Convert s*pow(10,d) into real */
971	  if( s==0 ){
972	    *pResult = 0.0;
973	    mState |= 4;
974	  }else{
975	    *pResult = sqlite3Fp10Convert2(s,d);
976	  }
977	  if( neg ) *pResult = -*pResult;
978	  assert( !sqlite3IsNaN(*pResult) );
979	
980	  /* return true if number and no extra non-whitespace characters after */
981	  if( z[0]==0 ){
982	    return mState;
983	  }
984	  if( sqlite3Isspace(z[0]) ){
985	    do{ z++; }while( sqlite3Isspace(*z) );
986	    if( z[0]==0 ){
987	      return mState;
988	    }
989	  }
990	  return 0xfffffff0 | mState;
991	#else
992	  return sqlite3Atoi64(z, pResult, strlen(z), SQLITE_UTF8)==0;
993	#endif /* SQLITE_OMIT_FLOATING_POINT */
994	}
