1025	/*
1026	** Render an unsigned 64-bit integer as text onto the end of a 2-byte
1027	** aligned buffer that is SQLITE_U64_DIGIT+1 bytes long.  The last byte
1028	** of the buffer will be filled with a \000 byte.
1029	**
1030	** Return the index into the buffer of the first byte.
1031	**
1032	** This routine is used on platforms where u64-division is slow because
1033	** it is not available in hardware and has to be emulated in software.
1034	** It seeks to minimize the number of u64 divisions and use u32 divisions
1035	** instead.  It is slower on platforms that have hardware u64 division,
1036	** but much faster on platforms that do not.
1037	*/
1038	static int sqlite3UInt64ToText(u64 v, char *zOut){
1039	  u32 x32, kk;
1040	  int i;
1041	  zOut[SQLITE_U64_DIGITS] = 0;
1042	  i = SQLITE_U64_DIGITS;
1043	  assert( TWO_BYTE_ALIGNMENT(&sqlite3DigitPairs.a[0]) );
1044	  assert( TWO_BYTE_ALIGNMENT(zOut) );
1045	  while( (v>>32)!=0 ){
1046	    u32 y, x0, x1, y0, y1;
1047	    x32 = v % 100000000;
1048	    v   = v / 100000000;
1049	    y = x32 % 10000;
1050	    x32 /= 10000;
1051	    x1 = x32 / 100;
1052	    x0 = x32 % 100;
1053	    y1 = y / 100;
1054	    y0 = y % 100;
1055	    assert( i>=8 );
1056	    i -= 8;
1057	    *(u16*)(&zOut[i]) = *(u16*)&sqlite3DigitPairs.a[x1*2];
1058	    *(u16*)(&zOut[i+2]) = *(u16*)&sqlite3DigitPairs.a[x0*2];
1059	    *(u16*)(&zOut[i+4]) = *(u16*)&sqlite3DigitPairs.a[y1*2];
1060	    *(u16*)(&zOut[i+6]) = *(u16*)&sqlite3DigitPairs.a[y0*2];
1061	  }
1062	  x32 = v;
1063	  while( x32>=10 ){
1064	    kk  = x32 % 100;
1065	    x32 = x32 / 100;
1066	    assert( TWO_BYTE_ALIGNMENT(&sqlite3DigitPairs.a[kk*2]) );
1067	    assert( i>=2 );
1068	    i -= 2;
1069	    assert( TWO_BYTE_ALIGNMENT(&zOut[i]) );
1070	    *(u16*)(&zOut[i]) = *(u16*)&sqlite3DigitPairs.a[kk*2];
1071	  }
1072	  if( x32 ){
1073	    assert( i>0 );
1074	    zOut[--i] = x32 + '0';
1075	  }
1076	  return i;
