1097	  }else if( v==0 ){
1098	    zOut[0] = '0';
1099	    zOut[1] = 0;
1100	    return 1;
1101	  }else{
1102	    x = (v==SMALLEST_INT64) ? ((u64)1)<<63 : (u64)-v;
1103	  }
1104	#ifdef SQLITE_AVOID_U64_DIVIDE
