1812	    return 2;
1813	  }
1814	  if( (p[2] & 0x80)==0 ){
1815	    /* This is the three-byte case */
1816	    *v = ((p[0]&0x7f)<<14) | ((p[1]&0x7f)<<7) | p[2];
1817	    return 3;
1818	  }
1819	  /* four or more bytes */
1820	  n = sqlite3GetVarint(p, &v64);
1821	  assert( n>3 && n<=9 );
1822	  if( (v64 & SQLITE_MAX_U32)!=v64 ){
1823	    *v = 0xffffffff;
1824	  }else{
1825	    *v = (u32)v64;
1826	  }
1827	  return n;
