1951	  }
1952	  eOpenState = db->eOpenState;
1953	  if( eOpenState!=SQLITE_STATE_OPEN ){
1954	    if( sqlite3SafetyCheckSickOrOk(db) ){
1955	      testcase( sqlite3GlobalConfig.xLog!=0 );
