1983	int sqlite3AddInt64(i64 *pA, i64 iB){
1984	#if GCC_VERSION>=5004000 && !defined(__INTEL_COMPILER)
1985	  return __builtin_add_overflow(*pA, iB, pA);
1986	#else
1987	  i64 iA = *pA;
1988	  testcase( iA==0 ); testcase( iA==1 );
1989	  testcase( iB==-1 ); testcase( iB==0 );
1990	  if( iB>=0 ){
1991	    testcase( iA>0 && LARGEST_INT64 - iA == iB );
1992	    testcase( iA>0 && LARGEST_INT64 - iA == iB - 1 );
1993	    if( iA>0 && LARGEST_INT64 - iA < iB ) return 1;
1994	  }else{
1995	    testcase( iA<0 && -(iA + LARGEST_INT64) == iB + 1 );
1996	    testcase( iA<0 && -(iA + LARGEST_INT64) == iB + 2 );
1997	    if( iA<0 && -(iA + LARGEST_INT64) > iB + 1 ) return 1;
1998	  }
1999	  *pA += iB;
2000	  return 0;
2001	#endif
