2003	int sqlite3SubInt64(i64 *pA, i64 iB){
2004	#if GCC_VERSION>=5004000 && !defined(__INTEL_COMPILER)
2005	  return __builtin_sub_overflow(*pA, iB, pA);
2006	#else
2007	  testcase( iB==SMALLEST_INT64+1 );
2008	  if( iB==SMALLEST_INT64 ){
2009	    testcase( (*pA)==(-1) ); testcase( (*pA)==0 );
2010	    if( (*pA)>=0 ) return 1;
2011	    *pA -= iB;
2012	    return 0;
2013	  }else{
2014	    return sqlite3AddInt64(pA, -iB);
2015	  }
2016	#endif
2017	}
2018	int sqlite3MulInt64(i64 *pA, i64 iB){
2019	#if GCC_VERSION>=5004000 && !defined(__INTEL_COMPILER)
2020	  return __builtin_mul_overflow(*pA, iB, pA);
2021	#else
2022	  i64 iA = *pA;
2023	  if( iB>0 ){
2024	    if( iA>LARGEST_INT64/iB ) return 1;
2025	    if( iA<SMALLEST_INT64/iB ) return 1;
2026	  }else if( iB<0 ){
2027	    if( iA>0 ){
2028	      if( iB<SMALLEST_INT64/iA ) return 1;
2029	    }else if( iA<0 ){
2030	      if( iB==SMALLEST_INT64 ) return 1;
2031	      if( iA==SMALLEST_INT64 ) return 1;
2032	      if( -iA>LARGEST_INT64/-iB ) return 1;
2033	    }
2034	  }
2035	  *pA = iA*iB;
