2081	/*
2082	** Find (an approximate) sum of two LogEst values.  This computation is
2083	** not a simple "+" operator because LogEst is stored as a logarithmic
2084	** value.
2085	**
2086	*/
2087	LogEst sqlite3LogEstAdd(LogEst a, LogEst b){
2088	  static const unsigned char x[] = {
2089	     10, 10,                         /* 0,1 */
2090	      9, 9,                          /* 2,3 */
2091	      8, 8,                          /* 4,5 */
2092	      7, 7, 7,                       /* 6,7,8 */
2093	      6, 6, 6,                       /* 9,10,11 */
2094	      5, 5, 5,                       /* 12-14 */
2095	      4, 4, 4, 4,                    /* 15-18 */
2096	      3, 3, 3, 3, 3, 3,              /* 19-24 */
2097	      2, 2, 2, 2, 2, 2, 2,           /* 25-31 */
2098	  };
2099	  if( a>=b ){
2100	    if( a>b+49 ) return a;
2101	    if( a>b+31 ) return a+1;
2102	    return a+x[a-b];
2103	  }else{
2104	    if( b>a+49 ) return b;
2105	    if( b>a+31 ) return b+1;
2106	    return b+x[b-a];
