2110	/*
2111	** Convert an integer into a LogEst.  In other words, compute an
2112	** approximation for 10*log2(x).
2113	*/
2114	LogEst sqlite3LogEst(u64 x){
2115	  static LogEst a[] = { 0, 2, 3, 5, 6, 7, 8, 9 };
2116	  LogEst y = 40;
2117	  if( x<8 ){
2118	    if( x<2 ) return 0;
2119	    while( x<8 ){  y -= 10; x <<= 1; }
2120	  }else{
2121	#if GCC_VERSION>=5004000
2122	    int i = 60 - __builtin_clzll(x);
2123	    y += i*10;
2124	    x >>= i;
2125	#else
2126	    while( x>255 ){ y += 40; x >>= 4; }  /*OPTIMIZATION-IF-TRUE*/
2127	    while( x>15 ){  y += 10; x >>= 1; }
2128	#endif
2129	  }
2130	  return a[x&7] + y - 10;
