2133	/*
2134	** Convert a double into a LogEst
2135	** In other words, compute an approximation for 10*log2(x).
2136	*/
2137	LogEst sqlite3LogEstFromDouble(double x){
2138	  u64 a;
2139	  LogEst e;
2140	  assert( sizeof(x)==8 && sizeof(a)==8 );
2141	  if( x<=1 ) return 0;
2142	  if( x<=2000000000 ) return sqlite3LogEst((u64)x);
2143	  memcpy(&a, &x, 8);
