2154	  x /= 10;
2155	  if( n>=5 ) n -= 2;
2156	  else if( n>=1 ) n -= 1;
2157	  if( x>60 ) return (u64)LARGEST_INT64;
2158	  return x>=3 ? (n+8)<<(x-3) : (n+8)>>(3-x);
