2160	
2161	/*
2162	** Add a new name/number pair to a VList.  This might require that the
2163	** VList object be reallocated, so return the new VList.  If an OOM
2164	** error occurs, the original VList returned and the
2165	** db->mallocFailed flag is set.
2166	**
2167	** A VList is really just an array of integers.  To destroy a VList,
2168	** simply pass it to sqlite3DbFree().
2169	**
2170	** The first integer is the number of integers allocated for the whole
2171	** VList.  The second integer is the number of integers actually used.
2172	** Each name/number pair is encoded by subsequent groups of 3 or more
2173	** integers.
2174	**
2175	** Each name/number pair starts with two integers which are the numeric
2176	** value for the pair and the size of the name/number pair, respectively.
2177	** The text name overlays one or more following integers.  The text name
2178	** is always zero-terminated.
2179	**
2180	** Conceptually:
2181	**
2182	**    struct VList {
2183	**      int nAlloc;   // Number of allocated slots
2184	**      int nUsed;    // Number of used slots
2185	**      struct VListEntry {
2186	**        int iValue;    // Value for this entry
2187	**        int nSlot;     // Slots used by this entry
2188	**        // ... variable name goes here
2189	**      } a[0];
2190	**    }
2191	**
2192	** During code generation, pointers to the variable names within the
2193	** VList are taken.  When that happens, nAlloc is set to zero as an
2194	** indication that the VList may never again be enlarged, since the
2195	** accompanying realloc() would invalidate the pointers.
2196	*/
2197	VList *sqlite3VListAdd(
2198	  sqlite3 *db,           /* The database connection used for malloc() */
2199	  VList *pIn,            /* The input VList.  Might be NULL */
2200	  const char *zName,     /* Name of symbol to add */
2201	  int nName,             /* Bytes of text in zName */
2202	  int iVal               /* Value to associate with zName */
2203	){
2204	  int nInt;              /* number of sizeof(int) objects needed for zName */
2205	  char *z;               /* Pointer to where zName will be stored */
2206	  int i;                 /* Index in pIn[] where zName is stored */
2207	
2208	  nInt = nName/4 + 3;
2209	  assert( pIn==0 || pIn[0]>=3 );  /* Verify ok to add new elements */
2210	  if( pIn==0 || pIn[1]+nInt > pIn[0] ){
2211	    /* Enlarge the allocation */
2212	    sqlite3_int64 nAlloc = (pIn ? 2*(sqlite3_int64)pIn[0] : 10) + nInt;
2213	    VList *pOut = sqlite3DbRealloc(db, pIn, nAlloc*sizeof(int));
2214	    if( pOut==0 ) return pIn;
2215	    if( pIn==0 ) pOut[1] = 2;
2216	    pIn = pOut;
2217	    pIn[0] = nAlloc;
2218	  }
2219	  i = pIn[1];
2220	  pIn[i] = iVal;
2221	  pIn[i+1] = nInt;
2222	  z = (char*)&pIn[i+2];
2223	  pIn[1] = i+nInt;
2224	  assert( pIn[1]<=pIn[0] );
2225	  memcpy(z, zName, nName);
2226	  z[nName] = 0;
2227	  return pIn;
2228	}
