2230	/*
2231	** Return a pointer to the name of a variable in the given VList that
2232	** has the value iVal.  Or return a NULL if there is no such variable in
2233	** the list
2234	*/
2235	const char *sqlite3VListNumToName(VList *pIn, int iVal){
2236	  int i, mx;
2237	  if( pIn==0 ) return 0;
2238	  mx = pIn[1];
2239	  i = 2;
2240	  do{
2241	    if( pIn[i]==iVal ) return (char*)&pIn[i+2];
2242	    i += pIn[i+1];
2243	  }while( i<mx );
2244	  return 0;
2245	}
