2256	  do{
2257	    const char *z = (const char*)&pIn[i+2];
2258	    if( strncmp(z,zName,nName)==0 && z[nName]==0 ) return pIn[i];
2259	    i += pIn[i+1];
2260	  }while( i<mx );
2261	  return 0;
2262	}
