558	/*
559	** The public interface to sqlite3Realloc.  Make sure that the memory
560	** subsystem is initialized prior to invoking sqliteRealloc.
561	*/
562	void *sqlite3_realloc(void *pOld, int n){
563	#ifndef SQLITE_OMIT_AUTOINIT
564	  if( sqlite3_initialize() ) return 0;
565	#endif
566	  if( n<0 ) n = 0;  /* IMP: R-26507-47431 */
567	  return sqlite3Realloc(pOld, n);
568	}
569	void *sqlite3_realloc64(void *pOld, sqlite3_uint64 n){
570	#ifndef SQLITE_OMIT_AUTOINIT
571	  if( sqlite3_initialize() ) return 0;
572	#endif
573	  return sqlite3Realloc(pOld, n);
574	}
