577	/*
578	** Allocate and zero memory.
579	*/ 
580	void *sqlite3MallocZero(u64 n){
581	  void *p = sqlite3Malloc(n);
582	  if( p ){
583	    memset(p, 0, (size_t)n);
584	  }
585	  return p;
586	}
587	
588	/*
589	** Allocate and zero memory.  If the allocation fails, make
590	** the mallocFailed flag in the connection pointer.
591	*/
592	void *sqlite3DbMallocZero(sqlite3 *db, u64 n){
593	  void *p;
594	  testcase( db==0 );
595	  p = sqlite3DbMallocRaw(db, n);
596	  if( p ) memset(p, 0, (size_t)n);
597	  return p;
598	}
