601	/* Finish the work of sqlite3DbMallocRawNN for the unusual and
602	** slower case when the allocation cannot be fulfilled using lookaside.
603	*/
604	static SQLITE_NOINLINE void *dbMallocRawFinish(sqlite3 *db, u64 n){
605	  void *p;
606	  assert( db!=0 );
607	  p = sqlite3Malloc(n);
608	  if( !p ) sqlite3OomFault(db);
609	  sqlite3MemdebugSetType(p, 
610	         (db->lookaside.bDisable==0) ? MEMTYPE_LOOKASIDE : MEMTYPE_HEAP);
611	  return p;
612	}
613	
614	/*
615	** Allocate memory, either lookaside (if possible) or heap.  
616	** If the allocation fails, set the mallocFailed flag in
617	** the connection pointer.
618	**
619	** If db!=0 and db->mallocFailed is true (indicating a prior malloc
620	** failure on the same database connection) then always return 0.
621	** Hence for a particular database connection, once malloc starts
622	** failing, it fails consistently until mallocFailed is reset.
623	** This is an important assumption.  There are many places in the
624	** code that do things like this:
625	**
626	**         int *a = (int*)sqlite3DbMallocRaw(db, 100);
627	**         int *b = (int*)sqlite3DbMallocRaw(db, 200);
628	**         if( b ) a[10] = 9;
629	**
630	** In other words, if a subsequent malloc (ex: "b") worked, it is assumed
631	** that all prior mallocs (ex: "a") worked too.
632	**
633	** The sqlite3MallocRawNN() variant guarantees that the "db" parameter is
634	** not a NULL pointer.
635	*/
636	void *sqlite3DbMallocRaw(sqlite3 *db, u64 n){
637	  void *p;
638	  if( db ) return sqlite3DbMallocRawNN(db, n);
639	  p = sqlite3Malloc(n);
640	  sqlite3MemdebugSetType(p, MEMTYPE_HEAP);
641	  return p;
642	}
643	void *sqlite3DbMallocRawNN(sqlite3 *db, u64 n){
644	#ifndef SQLITE_OMIT_LOOKASIDE
645	  LookasideSlot *pBuf;
646	  assert( db!=0 );
647	  assert( sqlite3_mutex_held(db->mutex) );
648	  assert( db->pnBytesFreed==0 );
649	  if( n>db->lookaside.sz ){
650	    if( !db->lookaside.bDisable ){
651	      db->lookaside.anStat[1]++;      
652	    }else if( db->mallocFailed ){
653	      return 0;
654	    }
655	    return dbMallocRawFinish(db, n);
656	  }
657	#ifndef SQLITE_OMIT_TWOSIZE_LOOKASIDE
658	  if( n<=LOOKASIDE_SMALL ){
659	    if( (pBuf = db->lookaside.pSmallFree)!=0 ){
660	      db->lookaside.pSmallFree = pBuf->pNext;
661	      db->lookaside.anStat[0]++;
662	      return (void*)pBuf;
663	    }else if( (pBuf = db->lookaside.pSmallInit)!=0 ){
664	      db->lookaside.pSmallInit = pBuf->pNext;
665	      db->lookaside.anStat[0]++;
666	      return (void*)pBuf;
667	    }
668	  }
669	#endif
670	  if( (pBuf = db->lookaside.pFree)!=0 ){
671	    db->lookaside.pFree = pBuf->pNext;
672	    db->lookaside.anStat[0]++;
673	    return (void*)pBuf;
674	  }else if( (pBuf = db->lookaside.pInit)!=0 ){
675	    db->lookaside.pInit = pBuf->pNext;
676	    db->lookaside.anStat[0]++;
677	    return (void*)pBuf;
678	  }else{
679	    db->lookaside.anStat[2]++;
680	  }
681	#else
682	  assert( db!=0 );
683	  assert( sqlite3_mutex_held(db->mutex) );
684	  assert( db->pnBytesFreed==0 );
685	  if( db->mallocFailed ){
686	    return 0;
687	  }
688	#endif
689	  return dbMallocRawFinish(db, n);
690	}
691	
692	/* Forward declaration */
693	static SQLITE_NOINLINE void *dbReallocFinish(sqlite3 *db, void *p, u64 n);
694	
695	/*
696	** Resize the block of memory pointed to by p to n bytes. If the
697	** resize fails, set the mallocFailed flag in the connection object.
698	*/
699	void *sqlite3DbRealloc(sqlite3 *db, void *p, u64 n){
700	  assert( db!=0 );
701	  if( p==0 ) return sqlite3DbMallocRawNN(db, n);
702	  assert( sqlite3_mutex_held(db->mutex) );
703	  if( ((uptr)p)<(uptr)db->lookaside.pEnd ){
704	#ifndef SQLITE_OMIT_TWOSIZE_LOOKASIDE
705	    if( ((uptr)p)>=(uptr)db->lookaside.pMiddle ){
706	      if( n<=LOOKASIDE_SMALL ) return p;
707	    }else
708	#endif
709	    if( ((uptr)p)>=(uptr)db->lookaside.pStart ){
710	      if( n<=db->lookaside.szTrue ) return p;
711	    }
712	  }
713	  return dbReallocFinish(db, p, n);
714	}
715	static SQLITE_NOINLINE void *dbReallocFinish(sqlite3 *db, void *p, u64 n){
716	  void *pNew = 0;
717	  assert( db!=0 );
718	  assert( p!=0 );
719	  if( db->mallocFailed==0 ){
720	    if( isLookaside(db, p) ){
721	      pNew = sqlite3DbMallocRawNN(db, n);
722	      if( pNew ){
723	        memcpy(pNew, p, lookasideMallocSize(db, p));
724	        sqlite3DbFree(db, p);
725	      }
726	    }else{
727	      assert( sqlite3MemdebugHasType(p, (MEMTYPE_LOOKASIDE|MEMTYPE_HEAP)) );
728	      assert( sqlite3MemdebugNoType(p, (u8)~(MEMTYPE_LOOKASIDE|MEMTYPE_HEAP)) );
729	      sqlite3MemdebugSetType(p, MEMTYPE_HEAP);
730	      pNew = sqlite3Realloc(p, n);
731	      if( !pNew ){
732	        sqlite3OomFault(db);
733	      }
734	      sqlite3MemdebugSetType(pNew,
735	            (db->lookaside.bDisable==0 ? MEMTYPE_LOOKASIDE : MEMTYPE_HEAP));
736	    }
737	  }
738	  return pNew;
739	}
740	
741	/*
742	** Attempt to reallocate p.  If the reallocation fails, then free p
743	** and set the mallocFailed flag in the database connection.
744	*/
745	void *sqlite3DbReallocOrFree(sqlite3 *db, void *p, u64 n){
746	  void *pNew;
747	  pNew = sqlite3DbRealloc(db, p, n);
748	  if( !pNew ){
749	    sqlite3DbFree(db, p);
750	  }
751	  return pNew;
752	}
753	
754	/*
755	** Make a copy of a string in memory obtained from sqliteMalloc(). These 
756	** functions call sqlite3MallocRaw() directly instead of sqliteMalloc(). This
757	** is because when memory debugging is turned on, these two functions are 
758	** called via macros that record the current file and line number in the
759	** ThreadData structure.
760	*/
761	char *sqlite3DbStrDup(sqlite3 *db, const char *z){
762	  char *zNew;
763	  size_t n;
764	  if( z==0 ){
765	    return 0;
766	  }
767	  n = strlen(z) + 1;
768	  zNew = sqlite3DbMallocRaw(db, n);
769	  if( zNew ){
770	    memcpy(zNew, z, n);
771	  }
772	  return zNew;
773	}
774	char *sqlite3DbStrNDup(sqlite3 *db, const char *z, u64 n){
775	  char *zNew;
776	  assert( db!=0 );
777	  assert( z!=0 || n==0 );
778	  assert( (n&0x7fffffff)==n );
779	  zNew = z ? sqlite3DbMallocRawNN(db, n+1) : 0;
780	  if( zNew ){
781	    memcpy(zNew, z, (size_t)n);
782	    zNew[n] = 0;
783	  }
784	  return zNew;
785	}
786	
787	/*
788	** The text between zStart and zEnd represents a phrase within a larger
789	** SQL statement.  Make a copy of this phrase in space obtained form
790	** sqlite3DbMalloc().  Omit leading and trailing whitespace.
791	*/
792	char *sqlite3DbSpanDup(sqlite3 *db, const char *zStart, const char *zEnd){
793	  int n;
794	#ifdef SQLITE_DEBUG
795	  /* Because of the way the parser works, the span is guaranteed to contain
796	  ** at least one non-space character */
797	  for(n=0; sqlite3Isspace(zStart[n]); n++){ assert( &zStart[n]<zEnd ); }
798	#endif
799	  while( sqlite3Isspace(zStart[0]) ) zStart++;
800	  n = (int)(zEnd - zStart);
801	  while( sqlite3Isspace(zStart[n-1]) ) n--;
802	  return sqlite3DbStrNDup(db, zStart, n);
803	}
804	
805	/*
806	** Free any prior content in *pz and replace it with a copy of zNew.
807	*/
808	void sqlite3SetString(char **pz, sqlite3 *db, const char *zNew){
809	  char *z = sqlite3DbStrDup(db, zNew);
810	  sqlite3DbFree(db, *pz);
811	  *pz = z;
812	}
813	
814	/*
815	** Call this routine to record the fact that an OOM (out-of-memory) error
816	** has happened.  This routine will set db->mallocFailed, and also
817	** temporarily disable the lookaside memory allocator and interrupt
818	** any running VDBEs.
819	**
820	** Always return a NULL pointer so that this routine can be invoked using
821	**
822	**      return sqlite3OomFault(db);
823	**
824	** and thereby avoid unnecessary stack frame allocations for the overwhelmingly
825	** common case where no OOM occurs.
826	*/
827	void *sqlite3OomFault(sqlite3 *db){
828	  if( db->mallocFailed==0 && db->bBenignMalloc==0 ){
829	    db->mallocFailed = 1;
830	    if( db->nVdbeExec>0 ){
831	      AtomicStore(&db->u1.isInterrupted, 1);
832	    }
833	    DisableLookaside;
834	    if( db->pParse ){
835	      Parse *pParse;
836	      sqlite3ErrorMsg(db->pParse, "out of memory");
837	      db->pParse->rc = SQLITE_NOMEM_BKPT;
838	      for(pParse=db->pParse->pOuterParse; pParse; pParse = pParse->pOuterParse){
839	        pParse->nErr++;
840	        pParse->rc = SQLITE_NOMEM;
841	      } 
842	    }
843	  }
844	  return 0;
845	}
846	
847	/*
848	** This routine reactivates the memory allocator and clears the
849	** db->mallocFailed flag as necessary.
850	**
851	** The memory allocator is not restarted if there are running
852	** VDBEs.
853	*/
854	void sqlite3OomClear(sqlite3 *db){
855	  if( db->mallocFailed && db->nVdbeExec==0 ){
856	    db->mallocFailed = 0;
857	    AtomicStore(&db->u1.isInterrupted, 0);
858	    assert( db->lookaside.bDisable>0 );
859	    EnableLookaside;
860	  }
861	}
862	
863	/*
864	** Take actions at the end of an API call to deal with error codes.
865	*/
866	static SQLITE_NOINLINE int apiHandleError(sqlite3 *db, int rc){
867	  if( db->mallocFailed || rc==SQLITE_IOERR_NOMEM ){
868	    sqlite3OomClear(db);
869	    sqlite3Error(db, SQLITE_NOMEM);
870	    return SQLITE_NOMEM_BKPT;
871	  }
872	  return rc & db->errMask;
873	}
874	
875	/*
876	** This function must be called before exiting any API function (i.e. 
877	** returning control to the user) that has called sqlite3_malloc or
878	** sqlite3_realloc.
879	**
880	** The returned value is normally a copy of the second argument to this
881	** function. However, if a malloc() failure has occurred since the previous
882	** invocation SQLITE_NOMEM is returned instead. 
883	**
884	** If an OOM as occurred, then the connection error-code (the value
885	** returned by sqlite3_errcode()) is set to SQLITE_NOMEM.
886	*/
887	int sqlite3ApiExit(sqlite3* db, int rc){
888	  /* If the db handle must hold the connection handle mutex here.
889	  ** Otherwise the read (and possible write) of db->mallocFailed 
890	  ** is unsafe, as is the call to sqlite3Error().
891	  */
892	  assert( db!=0 );
893	  assert( sqlite3_mutex_held(db->mutex) );
894	  if( db->mallocFailed || rc ){
895	    return apiHandleError(db, rc);
896	  }
897	  return 0;
898	}
