```rust
// src/util/alloc.rs

use std::alloc::{GlobalAlloc, Layout, System};
use std::ptr::NonNull;

/// Internal allocation header that stores the size before the user pointer.
/// This is similar to SQLite's internal memstat tracking, but in our case
/// it's needed because Rust's GlobalAlloc requires explicit Layout.
#[repr(C)]
struct Header {
    size: usize,
    /// Original requested user size (vs aligned layout size)
    user_size: usize,
}

const HEADER_SIZE: usize = std::mem::size_of::<Header>();

/// Round up to alignment, similar to C's ROUND8().
fn round_up(n: usize, align: usize) -> usize {
    (n + align - 1) & !(align - 1)
}

/// Get the layout for a user-requested size with HEADER prefixed.
/// SQLite uses 8-byte alignment (EIGHT_BYTE_ALIGNMENT).
fn layout_for(size: usize) -> Option<Layout> {
    let total = round_up(HEADER_SIZE + size, std::mem::align_of::<Header>().max(8));
    Layout::from_size_align(total, 8).ok()
}

/// Allocate `size` bytes. Returns null for size=0 or on OOM.
pub fn Malloc(size: usize) -> *mut u8 {
    if size == 0 {
        return std::ptr::null_mut();
    }
    let layout = match layout_for(size) {
        Some(l) => l,
        None => return std::ptr::null_mut(),
    };
    // SAFETY: layout has non-zero size
    let raw = unsafe { System.alloc(layout) };
    if raw.is_null() {
        return std::ptr::null_mut();
    }
    // SAFETY: raw is valid; write header
    let header = raw as *mut Header;
    unsafe {
        (*header).size = layout.size();
        (*header).user_size = size;
    }
    unsafe { raw.add(HEADER_SIZE) }
}

/// Allocate and zero. Same as Malloc but with memset.
pub fn ZeroMalloc(size: usize) -> *mut u8 {
    let p = Malloc(size);
    if !p.is_null() {
        // SAFETY: Malloc returned size bytes
        unsafe { std::ptr::write_bytes(p, 0, size) };
    }
    p
}

/// Realloc. `old_size` is the user size of the original allocation.
/// If new_size is 0, frees the old pointer and returns null.
/// If old pointer is null, equivalent to Malloc(new_size).
/// If OOM, returns null AND keeps old pointer valid.
pub fn Realloc(p: *mut u8, old_size: usize, new_size: usize) -> *mut u8 {
    if p.is_null() {
        return Malloc(new_size);
    }
    if new_size == 0 {
        Free(p);
        return std::ptr::null_mut();
    }
    // For simplicity, allocate new + copy + free
    let new_p = Malloc(new_size);
    if new_p.is_null() {
        return std::ptr::null_mut();  // OOM: old pointer preserved
    }
    let copy_n = old_size.min(new_size);
    // SAFETY: p points to old_size bytes, new_p points to new_size bytes
    unsafe { std::ptr::copy_nonoverlapping(p, new_p, copy_n) };
    Free(p);
    new_p
}

/// Free a pointer returned by Malloc/ZeroMalloc/Realloc.
/// No-op for null pointer.
pub fn Free(p: *mut u8) {
    if p.is_null() {
        return;
    }
    // SAFETY: p was returned by Malloc; read header
    let header_ptr = unsafe { p.sub(HEADER_SIZE) };
    let size = unsafe { (*(header_ptr as *const Header)).size };
    // SAFETY: header_ptr is the original alloc base
    let layout = unsafe { Layout::from_size_align_unchecked(size, 8) };
    unsafe { System.dealloc(header_ptr, layout) };
}

/// Malloc with optional db context. On OOM, sets db.malloc_failed.
pub fn MallocWithDb(db: Option<&crate::SqliteDb>, size: usize) -> *mut u8 {
    let p = Malloc(size);
    if p.is_null() && size > 0 {
        if let Some(d) = db {
            d.set_malloc_failed();
        }
    }
    p
}
```

Hmm but I have a problem: the header alignment. Let me think again. The user pointer is returned as `raw.add(HEADER_SIZE)`. For 8-byte alignment of user pointer, `HEADER_SIZE` must be 8-byte aligned. `size_of::<Header>()` = 16 bytes (usize + usize on 64-bit). So HEADER_SIZE = 16, which is 8-aligned. Good.

But then the layout for the total allocation must be:
- Total size = HEADER_SIZE + user_size
