```rust
// src/util/alloc.rs

use std::alloc::{GlobalAlloc, Layout, System};
use std::ptr;

use crate::handle::SqliteDb;

/// Header preceding each allocation. Stores the size needed for dealloc/realloc.
#[repr(C)]
struct Header {
    /// User-requested size (may be smaller than `actual_size` due to alignment)
    user_size: u32,
    /// Actual layout size (rounded up to 8-byte alignment)
    actual_size: u32,
}

const HEADER_SIZE: usize = std::mem::size_of::<Header>();

/// SQLite's required alignment: 8 bytes.
const ALIGN: usize = 8;

/// 8-byte alignment (matches C EIGHT_BYTE_ALIGNMENT).
#[inline]
const fn align8(n: usize) -> usize {
    (n + ALIGN - 1) & !(ALIGN - 1)
}

/// Build a layout that includes the header and aligns to 8 bytes.
fn layout_with_header(user_size: usize) -> Option<Layout> {
    let total = align8(HEADER_SIZE + user_size);
    Layout::from_size_align(total, ALIGN).ok()
}

/// Internal `sqlite3Malloc` equivalent.
///
/// - `size == 0` returns null (matches C).
/// - On OOM returns null (does NOT panic, does NOT set `db.malloc_failed`).
///   Use `MallocWithDb` for the deferred-error path.
pub fn Malloc(size: usize) -> *mut u8 {
    if size == 0 {
        return ptr::null_mut();
    }
    let layout = match layout_with_header(size) {
        Some(l) => l,
        None => return ptr::null_mut(),
    };
    // SAFETY: layout has non-zero size (size > 0 implies total > 0).
    let raw = unsafe { System.alloc(layout) };
    if raw.is_null() {
        return ptr::null_mut();
    }
    // SAFETY: raw is valid, writable, and properly aligned for Header.
    let header_ptr = raw as *mut Header;
    unsafe {
        (*header_ptr).user_size = size as u32;
        (*header_ptr).actual_size = layout.size() as u32;
    }
    // SAFETY: raw is allocated for at least HEADER_SIZE bytes.
    unsafe { raw.add(HEADER_SIZE) }
}

/// Internal `sqlite3MallocZero` equivalent.
pub fn ZeroMalloc(size: usize) -> *mut u8 {
    let p = Malloc(size);
    if !p.is_null() {
        // SAFETY: p is valid for `size` bytes (Malloc's contract).
        unsafe { ptr::write_bytes(p, 0, size) };
    }
    p
}

/// Internal `sqlite3Realloc` equivalent.
///
/// - `p == null` behaves like `Malloc(new_size)`.
/// - `new_size == 0` frees `p` and returns null.
/// - On OOM, `p` remains valid and null is returned (matches C).
pub fn Realloc(p: *mut u8, new_size: usize) -> *mut u8 {
    if p.is_null() {
        return Malloc(new_size);
    }
    if new_size == 0 {
        Free(p);
        return ptr::null_mut();
    }
    // Read old header.
    // SAFETY: p was returned by Malloc/Realloc, so header at p-HEADER_SIZE is valid.
    let old_header = unsafe { &*(p.sub(HEADER_SIZE) as *const Header) };
    let old_user_size = old_header.user_size as usize;
    let old_actual_size = old_header.actual_size as usize;

    let new_layout = match layout_with_header(new_size) {
        Some(l) => l,
        None => return ptr::null_mut(),
    };

    // SAFETY: p-HEADER_SIZE was allocated with old_actual_size and ALIGN.
    //         If realloc returns non-null, ownership transfers; if null, p is still valid.
    let new_raw = unsafe {
        let layout = Layout::from_size_align(old_actual_size, ALIGN).unwrap();
        std::alloc::realloc(
            p.sub(HEADER_SIZE),
            layout,
            new_layout.size(),
        )
    };
    if new_raw.is_null() {
        return ptr::null_mut(); // OOM: old pointer preserved
    }
    // SAFETY: new_raw is valid and writable.
    let new_header = new_raw as *mut Header;
    unsafe {
        (*new_header).user_size = new_size as u32;
        (*new_header).actual_size = new_layout.size() as u32;
    }
    // SAFETY: new_raw is allocated for at least HEADER_SIZE bytes.
    unsafe { new_raw.add(HEADER_SIZE) }
}

/// Internal `sqlite3_free` equivalent. No-op for null.
pub fn Free(p: *mut u8) {
    if p.is_null() {
        return;
    }
    // SAFETY: p was returned by Malloc/Realloc.
    let header_ptr = unsafe { p.sub(HEADER_SIZE) };
    let actual_size = unsafe { (*(header_ptr as *const Header)).actual_size as usize };
    // SAFETY: header_ptr was allocated with actual_size and ALIGN.
    let layout = unsafe { Layout::from_size_align_unchecked(actual_size, ALIGN) };
    unsafe { System.dealloc(header_ptr, layout) };
}

/// Malloc with deferred OOM signaling on a `SqliteDb`.
///
/// - `size == 0` returns null without setting `db.malloc_failed`.
/// - On OOM, returns null and sets `db.malloc_failed = true`.
/// - This is the alignment of C's `sqlite3OomFault(db)` for the malloc family.
pub fn MallocWithDb(db: &SqliteDb, size: usize) -> *mut u8 {
    let p = Malloc(size);
    if p.is_null() && size > 0 {
        db.set_malloc_failed();
    }
    p
}

/// Returns the user-requested size of a previous allocation.
/// Returns 0 for null pointer.
pub fn Msize(p: *const u8) -> usize {
    if p.is_null() {
        return 0;
    }
    // SAFETY: p was returned by Malloc/Realloc.
    let header = unsafe { &*(p.sub(HEADER_SIZE) as *const Header) };
    header.user_size as usize
}
```

